describe('Navigation from Home Page to Example Page and Back', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com');
  });

  it('should navigate from home page to example page and back successfully', () => {
    // Verify home page content
    cy.get('h1').should('contain', 'Welcome to the internet');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible');
    cy.get('[data-testid="available-examples-heading"]').should('contain', 'Available Examples');

    // Navigate to example page
    cy.get('[data-testid="ab-testing-link"]').should('be.visible');
    cy.get('[data-testid="ab-testing-link"]').click();

    // Verify navigation to example page
    cy.url().should('include', '/abtest');
    cy.get('h3').should('be.visible');
    cy.get('h3').should('contain', 'A/B Testing');

    // Navigate back to home page
    cy.go('back');

    // Verify return to home page
    cy.url().should('include', '/');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible');
    cy.get('[data-testid="available-examples-heading"]').should('contain', 'Available Examples');
  });

  it('should handle navigation when example page link is missing or broken', () => {
    // Verify home page content
    cy.get('h1').should('contain', 'Welcome to the internet');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible');

    // Attempt to click a non-existent link
    cy.get('[data-testid="non-existent-link"]').should('not.exist');

    // Verify home page remains unchanged
    cy.url().should('include', '/');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible');

    // Verify navigation back button still works
    cy.visit('https://the-internet.herokuapp.com/abtest');
    cy.get('h3').should('contain', 'A/B Testing');
    cy.go('back');
    cy.url().should('include', '/');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible');
  });
});
